  async function start(customerId:string){const ctx={scope,customerId,businessDate:'2026-10-01',actorRef:'customer:'+customerId};const c=await service.start(ctx,{idempotencyKey:'start-'+randomUUID()});await service.verify(ctx,{challengePublicId:c.challengePublicId,verifiedPhone:{e164Phone:phone,providerReference:'verified-'+randomUUID(),verifiedAt:new Date().toISOString()},idempotencyKey:'verify-'+randomUUID()});return (await pool.query('SELECT public_id FROM mbox.membership_merge_cases WHERE tenant_id=$1 AND target_customer_id=$2',[tenantId,customerId])).rows[0].public_id as string}
