  let row=await get();expect(row.status).toBe('manual_review');const candidates=await app.inject(root+'/candidates?casePublicId='+caseId+'&expectedVersion='+row.nativeVersion);expect(candidates.statusCode,candidates.body).toBe(200);expect(candidates.json().data.rows).toHaveLength(2);expect(candidates.body).not.toContain(phone);const selectedId=(await pool.query('SELECT public_id FROM mbox.membership_recovery_candidates WHERE candidate_customer_id=$1',[source])).rows[0].public_id
  const selection={casePublicId:caseId,expectedVersion:row.nativeVersion,candidatePublicId:selectedId,reason:'结合本人凭据核对原会员'},selectKey='native-business-'+randomUUID();expect((await send('select',selection,approver,selectKey)).statusCode).toBe(200);expect((await send('select',selection,editor)).statusCode).toBe(409);row=await get();expect(row.status).toBe('pending_review')
  const decision={casePublicId:caseId,expectedVersion:row.nativeVersion,reason:'独立核对原会员、手机号及现场依据'},approveKey='native-business-'+randomUUID();expect((await send('approve',decision,approver)).statusCode).toBe(409);expect((await send('approve',decision,editor)).statusCode).toBe(409);const approved=await send('approve',decision,publisher,approveKey);expect(approved.statusCode,approved.body).toBe(200);expect(approved.json().data.row).toMatchObject({status:'executed',selectedCandidatePublicId:selectedId,approvedByEmployeeId:publisher})
  expect((await pool.query('SELECT merged_into_customer_id FROM mbox.customers WHERE id=$1',[source])).rows[0].merged_into_customer_id).toBe(target);expect((await pool.query('SELECT points_balance,lifetime_points,customer_id FROM mbox.customer_memberships WHERE member_no=$1',[prefix+'A'])).rows[0]).toEqual({points_balance:75,lifetime_points:100,customer_id:source});expect((await pool.query('SELECT merged_into_customer_id FROM mbox.customers WHERE id=$1',[other])).rows[0].merged_into_customer_id).toBeNull()
  await pool.query('DELETE FROM mbox.idempotency_records WHERE tenant_id=$1',[tenantId]);for(const [a,b,who,key,status]of [['contact',contactBody,editor,contactKey,null],['select',selection,approver,selectKey,'pending_review'],['approve',decision,publisher,approveKey,'executed']] as const){const res=await send(a,b,who,key);expect(res.statusCode,res.body).toBe(200);expect(res.json().meta.replayed).toBe(true);if(status)expect(res.json().data.row.status).toBe(status)}
  await pool.query('DELETE FROM mbox.idempotency_records WHERE tenant_id=$1',[tenantId]);const changed=await send('contact',{...contactBody,phone:'+8613900099999'},editor,contactKey);expect(changed.statusCode).toBe(409);expect(changed.json().error.commitDisposition).toBeUndefined()
  const audit=await pool.query("SELECT after_snapshot,metadata FROM mbox.audit_events WHERE tenant_id=$1 AND action='native.physical.receipt'",[tenantId]);expect(JSON.stringify(audit.rows)).not.toContain(phone)
