  const nextCase=await start(await customer());const pending=((await app.inject(root)).json().data.rows as Array<Record<string,unknown>>).find(r=>r.casePublicId===nextCase)!;const rejected=await send('reject',{casePublicId:nextCase,expectedVersion:pending.nativeVersion,reason:'本人凭据不足暂不合并'},publisher);expect(rejected.statusCode,rejected.body).toBe(200);expect(rejected.json().data.row.status).toBe('rejected')
